CREATE TABLE public.companies (
  id text PRIMARY KEY,
  name text NOT NULL,
  industry text NOT NULL,
  city text NOT NULL,
  employees text NOT NULL DEFAULT '',
  website text NOT NULL DEFAULT '',
  verified boolean NOT NULL DEFAULT false,
  about text NOT NULL DEFAULT '',
  initials text NOT NULL DEFAULT '',
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE public.jobs (
  id text PRIMARY KEY,
  title text NOT NULL,
  company_id text NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE,
  category text NOT NULL,
  city text NOT NULL,
  remote boolean NOT NULL DEFAULT false,
  employment_type text NOT NULL,
  experience text NOT NULL DEFAULT '',
  education text NOT NULL DEFAULT '',
  salary_min integer NOT NULL DEFAULT 0,
  salary_max integer NOT NULL DEFAULT 0,
  posted_days_ago integer NOT NULL DEFAULT 0,
  deadline text NOT NULL DEFAULT '',
  applicants integer NOT NULL DEFAULT 0,
  skills text[] NOT NULL DEFAULT '{}',
  summary text NOT NULL DEFAULT '',
  description text NOT NULL DEFAULT '',
  requirements text[] NOT NULL DEFAULT '{}',
  benefits text[] NOT NULL DEFAULT '{}',
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX idx_jobs_company ON public.jobs(company_id);
CREATE INDEX idx_jobs_category ON public.jobs(category);
CREATE INDEX idx_jobs_city ON public.jobs(city);

GRANT SELECT ON public.companies TO anon;
GRANT SELECT ON public.companies TO authenticated;
GRANT ALL ON public.companies TO service_role;
GRANT SELECT ON public.jobs TO anon;
GRANT SELECT ON public.jobs TO authenticated;
GRANT ALL ON public.jobs TO service_role;

ALTER TABLE public.companies ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.jobs ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Companies are publicly readable" ON public.companies FOR SELECT TO anon, authenticated USING (true);
CREATE POLICY "Jobs are publicly readable" ON public.jobs FOR SELECT TO anon, authenticated USING (true);

