INSERT INTO public.jobs (id,title,company_id,category,city,remote,employment_type,experience,education,salary_min,salary_max,posted_days_ago,deadline,applicants,skills,summary,description,requirements,benefits) VALUES ('senior-frontend-engineer-aster','Senior Frontend Engineer','aster-tech','Software & IT','Addis Ababa',true,'Full-time','5+ years','BSc in Computer Science or related',65000,95000,2,'2026-09-05',48,ARRAY['React','TypeScript','Tailwind CSS','REST APIs','Testing']::text[],'Lead the web experience for a payments platform used by more than two million Ethiopians every month.','You will own the front-end architecture of our merchant and consumer dashboards, working closely with product design and backend teams to ship reliable, accessible interfaces on slow networks.',ARRAY['5+ years building production React applications','Strong TypeScript and modern CSS skills','Experience optimising for low-bandwidth mobile users','Comfortable mentoring mid-level engineers']::text[],ARRAY['Hybrid schedule','Private medical cover','Annual learning budget','Transport allowance']::text[]);
